using Xunit;
using ReviveOS.Browser;
using ReviveOS.Core;
public class ChromeTests {
 [Fact]public void OnlyDocumentedPerformancePoliciesAllowed(){Assert.Throws<ArgumentException>(()=>ChromePolicyBackend.Get("SafeBrowsingEnabled"));Assert.Throws<ArgumentException>(()=>ChromePolicyBackend.Get("PasswordManagerEnabled"));Assert.Throws<IOException>(()=>ChromePolicyBackend.ValidateValue("HighEfficiencyModeEnabled","2"));Assert.Throws<IOException>(()=>ChromePolicyBackend.ValidateValue("NetworkPredictionOptions","-1"));ChromePolicyBackend.ValidateValue("MemorySaverModeSavings","2");}
 [Fact]public void LightProfileUsesSeparateDirectoryWithoutDisablingProtection(){var args=ChromeRuntime.Arguments(true,"chrome://newtab/");Assert.Contains("--user-data-dir="+ChromeRuntime.LightProfile,args);Assert.DoesNotContain(args,x=>x.Contains("no-sandbox")||x.Contains("disable-web-security")||x.Contains("disable-extensions"));Assert.Empty(ChromeRuntime.Arguments(false));Assert.Throws<ArgumentException>(()=>ChromeRuntime.Arguments(false,"https://arbitrary.invalid/"));}
 [WindowsFact]public async Task PolicyRoundtripPreservesNeighbours(){if(!OperatingSystem.IsWindows())throw new PlatformNotSupportedException();var backend=new ChromePolicyBackend();var original=await backend.Read("HighEfficiencyModeEnabled");using var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(ChromePolicyBackend.KeyPath);var sentinel="ReviveOSTest_"+Guid.NewGuid().ToString("N");key.SetValue(sentinel,"preserve");var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));var journal=new ChangeJournal(Path.Combine(dir,"changes.json"),backend);try{await journal.Apply("HighEfficiencyModeEnabled",original=="1"?"0":"1");Assert.Equal("preserve",key.GetValue(sentinel));await journal.Restore();Assert.Equal(original,await backend.Read("HighEfficiencyModeEnabled"));Assert.Equal("preserve",key.GetValue(sentinel));}finally{try{await journal.Restore();}finally{key.DeleteValue(sentinel,false);if(Directory.Exists(dir))Directory.Delete(dir,true);}}}
 [WindowsFact]public async Task RealChromeWindowProducesBoundedMeasurement(){var exe=ChromeRuntime.FindChrome();Assert.NotNull(exe);var result=await ChromeRuntime.MeasureLaunch(true);try{Assert.True(result.WindowObservedMs>=0&&result.WindowObservedMs<45000);Assert.True(result.WindowProcessId>0);}finally{try{using var p=System.Diagnostics.Process.GetProcessById(result.WindowProcessId);p.CloseMainWindow();using var graceful=new CancellationTokenSource(TimeSpan.FromSeconds(15));try{await p.WaitForExitAsync(graceful.Token);}catch(OperationCanceledException){
 // Test fixture only: this process was just created in an empty, isolated profile on the runner.
 // Production measurement never terminates the user's browser.
 p.Kill(true);using var cleanup=new CancellationTokenSource(TimeSpan.FromSeconds(10));await p.WaitForExitAsync(cleanup.Token);
 }}catch(ArgumentException){}}}
}
